// Error is a typed runtime error produced by the expression runtime.
// It carries a classification (ErrorType*) used by the errtype() builtin.
// Runtime errors that do not originate from the expression runtime (for
// example errors returned by Go functions used in the expression) are not
// wrapped and are classified as "custom".
type Error struct {
	Type    string
	Message string
}

func (e *Error) Error() string {
	return e.Message
}

// NewError returns a new typed runtime error.
func NewError(t, message string) *Error {
	return &Error{Type: t, Message: message}
}

// ErrorMessage returns the message of a runtime error value. It accepts any
// value, including *Error, error, string, or arbitrary values.
func ErrorMessage(v any) string {
	switch t := v.(type) {
	case nil:
		return ""
	case *Error:
		return t.Message
	case error:
		return t.Error()
	case string:
		return t
	default:
		return fmt.Sprintf("%v", t)
	}
}

// ErrorType classifies a caught runtime error.
//
//	"index"      for out-of-range/bounds errors
//	"conversion" for type-conversion failures
//	"type"       for type-mismatch/assertion errors
//	"nil"        for nil-pointer/reference errors
//	"retry"      for retry-exhaustion errors
//	"custom"     for all other errors, including those from throw()
//	"none"       when the input is nil
func ErrorType(v any) string {
	if v == nil {
		return ErrorTypeNone
	}
	if e, ok := v.(*Error); ok {
		if e.Type != "" {
			return e.Type
		}
	}
	msg := ErrorMessage(v)
	// Go-native panics (bounds checks, nil dereferences) are not *Error
	// values; classify them by their message.
	switch {
	case strings.HasPrefix(msg, "runtime error:"):
		switch {
		case strings.Contains(msg, "index out of range"), strings.Contains(msg, "slice bounds out of range"):
			return ErrorTypeIndex
		case strings.Contains(msg, "nil pointer dereference"), strings.Contains(msg, "invalid memory address"):
			return ErrorTypeNil
		default:
			return ErrorTypeCustom
		}
	case strings.Contains(msg, "index out of range"), strings.Contains(msg, "slice bounds out of range"):
		return ErrorTypeIndex
	case strings.Contains(msg, "invalid memory address or nil pointer dereference"):
		return ErrorTypeNil
	default:
		return ErrorTypeCustom
	}
}
