// compileTry emits bytecode for a try expression with the given body,
// optional catch handler and optional finally body.
func (c *compiler) compileTry(
	body Node,
	hasCatch bool,
	catchBody Node,
	catchName string,
	catchMatch string,
	catchHasMatch bool,
	finallyNode Node,
) {
	layout := &TryLayout{
		ErrorVar:  -1,
		ResultVar: c.addVariable("$tryResult"),
	}
	if hasCatch && catchName != "" {
		layout.ErrorVar = c.addVariable(catchName)
	}
	layout.Match = catchMatch
	layout.HasMatch = catchHasMatch

	idx := len(c.tryLayouts)
	c.tryLayouts = append(c.tryLayouts, layout)
	c.emit(OpTryBegin, idx)

	layout.BodyIP = len(c.bytecode)
	c.compile(body)
	c.emit(OpStore, layout.ResultVar)
	// Skip the catch block when the body succeeded.
	skipCatch := c.emit(OpJump, placeholder)

	if hasCatch {
		layout.CatchIP = len(c.bytecode)
		if catchName != "" {
			c.beginScope(catchName, layout.ErrorVar)
		}
		c.compile(catchBody)
		if catchName != "" {
			c.endScope()
		}
		c.emit(OpStore, layout.ResultVar)
	}
	c.patchJump(skipCatch)

	if finallyNode != nil {
		layout.FinallyIP = len(c.bytecode)
		c.emit(OpTryFinally)
		c.compile(finallyNode)
		c.emit(OpPop)
	}
	c.emit(OpTryEnd)
}
```

