// compileTry emits bytecode for a try expression.
//
//	OpTryBegin        push a try frame
//	<body>            leaves one value on the stack
//	OpStore result    remember the successful result
//	OpJump            skip the catch block
//	<catch>           leaves one value on the stack (error bound to a var)
//	OpStore result    remember the catch result
//	OpTryFinally      (only when finally is present)
//	<finally>         its value is discarded
//	OpTryEnd          pop the frame; push the result, or re-throw the
//	                  in-flight exception if one is pending
func (c *compiler) compileTry(
	body Node,
	hasCatch bool,
	catchBody Node,
	catchName string,
	catchMatch string,
	catchHasMatch bool,
	finallyNode Node,
) {
	layout := &TryLayout{
		ErrorVar:  -1,
		ResultVar: c.addVariable("$tryResult"),
		Match:     catchMatch,
		HasMatch:  catchHasMatch,
	}
	if hasCatch && catchName != "" {
		layout.ErrorVar = c.addVariable(catchName)
	}

	idx := len(c.tryLayouts)
	c.tryLayouts = append(c.tryLayouts, layout)
	c.emit(OpTryBegin, idx)

	layout.BodyIP = len(c.bytecode)
	c.compile(body)
	c.emit(OpStore, layout.ResultVar)
	// Skip the catch block when the body succeeded.
	skipCatch := c.emit(OpJump, placeholder)

	if hasCatch {
