		if catchName != "" {
			c.beginScope(catchName, layout.ErrorVar)
		}
		c.compile(catchBody)
		if catchName != "" {
			c.endScope()
		}
		c.emit(OpStore, layout.ResultVar)
	}
	c.patchJump(skipCatch)

	if finallyNode != nil {
		layout.FinallyIP = len(c.bytecode)
		c.emit(OpTryFinally)
		c.compile(finallyNode)
		c.emit(OpPop)
	}
	c.emit(OpTryEnd)
}

