	e2 := &Env{}
	out, err = run(t, `try { Bump(); if (Get() < 100) { throw(Get()) } else { 1 }; "ok" } catch (err) { retry }`, e2)
	t.Logf("exhaustion case: out=%v err=%v count=%d", out, err, e2.Count)

	// errtype of the exhaustion error
	e3 := &Env{}
	out, err = run(t, `try { try { Bump(); if (Get() < 100) { throw(Get()) } else { 1 }; "ok" } catch (err) { retry } } catch (e2) { errtype(e2) }`, e3)
	t.Logf("exhaustion errtype: out=%v err=%v", out, err)

	// throw inside catch propagates (not caught by the same try)
	e4 := &Env{}
	out, err = run(t, `try { throw("first") } catch (err) { throw("second") }`, e4)
	t.Logf("catch-throw case: out=%v err=%v", out, err)

	// retry records: body runs exactly 4 times in the exhaustion case
	r := &RecEnv{}
	out, err = run(t, `try { Bump(); throw(Get()) } catch (err) { Note("catch"); retry }`, r)
	t.Logf("rec case: out=%v err=%v hist=%v", out, err, r.History)
}
