func (vm *VM) handleException(program *Program, ex vmException) bool {
	msg := runtime.ErrorMessage(ex.value)
	for len(vm.tryStack) > 0 {
		frame := vm.currTryFrame()
		switch frame.state {
		case tryStateBody:
			layout := frame.layout
			if layout.CatchIP != 0 && (!layout.HasMatch || strings.Contains(msg, layout.Match)) {
				vm.restoreTryFrame(frame)
				if layout.ErrorVar >= 0 {
					vm.Variables[layout.ErrorVar] = ex.value
				}
				frame.state = tryStateCatch
				vm.ip = layout.CatchIP
				return true
			}
			if layout.FinallyIP != 0 {
				vm.restoreTryFrame(frame)
				frame.state = tryStateFinally
				frame.pending = ex
				frame.hasPending = true
				vm.ip = layout.FinallyIP
				return true
			}
			vm.popTryFrame()
		case tryStateCatch:
			// An exception raised inside a catch body is not caught by
			// the same try expression.
			if frame.layout.FinallyIP != 0 {
				vm.restoreTryFrame(frame)
				frame.state = tryStateFinally
				frame.pending = ex
				frame.hasPending = true
				vm.ip = frame.layout.FinallyIP
				return true
			}
			vm.popTryFrame()
		case tryStateFinally:
			// An exception raised inside a finally body overrides any
			// prior error (or result) of the try expression.
			frame.pending = ex
			frame.hasPending = true
			vm.popTryFrame()
		}
	}
	return false
}

// pushTryFrame pushes a new try frame for the given layout.
func (vm *VM) pushTryFrame(layout *TryLayout) {
	vm.tryStack = append(vm.tryStack, &tryFrame{
		layout:    layout,
		stackLen:  len(vm.Stack),
		scopesLen: len(vm.Scopes),
	})
}

// popTryFrame removes and returns the innermost try frame.
func (vm *VM) popTryFrame() *tryFrame {
	frame := vm.tryStack[len(vm.tryStack)-1]
	vm.tryStack = vm.tryStack[:len(vm.tryStack)-1]
	return frame
}

// currTryFrame returns the innermost try frame, or nil when there is none.
func (vm *VM) currTryFrame() *tryFrame {
	if len(vm.tryStack) == 0 {
		return nil
	}
	return vm.tryStack[len(vm.tryStack)-1]
}

