new file mode 100644
index 0000000..5e11f56
--- /dev/null
+++ b/expr_error_handling_test.go
@@ -0,0 +1,248 @@
+package expr_test
+
+import (
+	"fmt"
+	"testing"
+
+	"github.com/expr-lang/expr"
+	"github.com/expr-lang/expr/internal/testify/assert"
+	"github.com/expr-lang/expr/internal/testify/require"
+	"github.com/expr-lang/expr/vm/runtime"
+)
+
+// ehCounter counts how many times its body-executing method was called.
+// Methods return values, since they are used as expression statements.
+type ehCounter struct{ Count int }
+
+func (c *ehCounter) Get() int  { return c.Count }
+func (c *ehCounter) Bump() int { c.Count++; return c.Count }
+
+type ehInner struct{ X int }
+
+// ehNilEnv holds a nil pointer; P.X panics on field access (unchecked
+// programs), and Deref panics with a Go nil-pointer dereference.
+type ehNilEnv struct{ P *ehInner }
+
+func (n *ehNilEnv) Deref() int { return (*n.P).X }
+
+func TestExpr_try_catch(t *testing.T) {
+	tests := []struct {
+		code string
+		env  any
+		want any
+	}{
+		{`try { 1 + 1 } catch { 0 }`, nil, 2},
+		{`try { 1 + 1 } catch (e) { 0 }`, nil, 2},
+		{`try { [1,2,3][5] } catch { 0 }`, nil, 0},
+		{`try { [1,2,3][5] } catch (e) { errtype(e) }`, nil, "index"},
+		{`try { int("abc") } catch (e) { errtype(e) }`, nil, "conversion"},
+		{`try { float("abc") } catch (e) { errtype(e) }`, nil, "conversion"},
+		{`try { throw("boom") } catch (e) { errtype(e) }`, nil, "custom"},
+		{`try { throw("boom") } catch (e) { string(e) }`, nil, "boom"},
+		{`try { throw("boom") } catch e { string(e) }`, nil, "boom"},
+		{`try { throw(42) } catch (e) { string(e) }`, nil, "42"},
+		{`try { Deref() } catch (e) { errtype(e) }`, &ehNilEnv{}, "nil"},
+		{`errtype(nil)`, nil, "none"},
+		{`try { throw("bad thing") } catch (e) is "bad" { "matched" }`, nil, "matched"},
+		{`try { throw("bad thing") } catch (e) is "other" { "no" }`, nil, nil},
+		{`try { try { throw("inner") } catch (e) { string(e) } } catch (e) { "outer" }`, nil, "inner"},
+		{`try { try { throw("inner") } catch (e) { throw(string(e)) } } catch (e) { string(e) }`, nil, "inner"},
+	}
+
+	for _, tt := range tests {
+		t.Run(tt.code, func(t *testing.T) {
+			// Unchecked evaluation (expr.Eval).
+			out, err := expr.Eval(tt.code, tt.env)
+			if tt.want == nil {
+				require.Error(t, err)
+			} else {
+				require.NoError(t, err)
+				assert.Equal(t, tt.want, out)
+			}
+
+			// Checked compilation (expr.Compile + expr.Run).
+			var opt []expr.Option
+			if tt.env != nil {
+				opt = append(opt, expr.Env(tt.env))
+			}
+			program, err := expr.Compile(tt.code, opt...)
+			require.NoError(t, err)
+			out, err = expr.Run(program, tt.env)
+			if tt.want == nil {
+				require.Error(t, err)
+			} else {
+				require.NoError(t, err)
+				assert.Equal(t, tt.want, out)
+			}
+		})
+	}
+}
+
+func TestExpr_try_catch_error_message(t *testing.T) {
+	// When the catch filter does not match, the original error propagates.
+	_, err := expr.Eval(`try { throw("bad thing") } catch (e) is "other" { "no" }`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "bad thing")
+
+	// An error raised inside a catch body is not caught by the same try.
+	_, err = expr.Eval(`try { throw("first") } catch (e) { throw("second") }`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "second")
+
+	// A top-level throw raises its value as a runtime error.
+	_, err = expr.Eval(`throw("top")`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "top")
+}
+
+func TestExpr_try_finally(t *testing.T) {
+	tests := []struct {
+		code string
+		env  any
+		want any
+	}{
+		{`try { 1 } finally { 2 }`, nil, 1},
+		{`try { throw("x") } catch { 1 } finally { 2 }`, nil, 1},
+	}
+	for _, tt := range tests {
+		t.Run(tt.code, func(t *testing.T) {
+			out, err := expr.Eval(tt.code, tt.env)
+			require.NoError(t, err)
+			assert.Equal(t, tt.want, out)
+
+			program, err := expr.Compile(tt.code)
+			require.NoError(t, err)
+			out, err = expr.Run(program, tt.env)
+			require.NoError(t, err)
+			assert.Equal(t, tt.want, out)
+		})
+	}
+
+	// finally executes after a successful body.
+	c := &ehCounter{}
+	out, err := expr.Eval(`try { Bump() } finally { Bump() }`, c)
+	require.NoError(t, err)
+	assert.Equal(t, 1, out)
+	assert.Equal(t, 2, c.Count)
+
+	// finally executes after a caught failure.
+	c = &ehCounter{}
+	out, err = expr.Eval(`try { Bump(); throw("x") } catch { 0 } finally { Bump() }`, c)
+	require.NoError(t, err)
+	assert.Equal(t, 0, out)
+	assert.Equal(t, 2, c.Count)
+
+	// An error raised in finally overrides the result of the try.
+	_, err = expr.Eval(`try { 1 } finally { throw("f") }`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "f")
+
+	// An error raised in finally overrides a caught error.
+	_, err = expr.Eval(`try { throw("b") } catch { 1 } finally { throw("f") }`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "f")
+}
+
+func TestExpr_try_function_form(t *testing.T) {
+	// On success the expression result is returned.
+	out, err := expr.Eval(`try(1 + 1, "fb")`, nil)
+	require.NoError(t, err)
+	assert.Equal(t, 2, out)
+
+	// On failure the fallback is returned.
+	out, err = expr.Eval(`try([1,2,3][5], "fb")`, nil)
+	require.NoError(t, err)
+	assert.Equal(t, "fb", out)
+
+	// The fallback is lazily evaluated: it is not evaluated on success.
+	c := &ehCounter{}
+	out, err = expr.Eval(`try(Bump(), Bump())`, c)
+	require.NoError(t, err)
+	assert.Equal(t, 1, out)
+	assert.Equal(t, 1, c.Count)
+
+	// The fallback is evaluated on failure.
+	out, err = expr.Eval(`try(throw("x"), "fb")`, nil)
+	require.NoError(t, err)
+	assert.Equal(t, "fb", out)
+
+	// Same semantics through the checked compilation path.
+	program, err := expr.Compile(`try(1 + 1, "fb")`)
+	require.NoError(t, err)
+	out, err = expr.Run(program, nil)
+	require.NoError(t, err)
+	assert.Equal(t, 2, out)
+}
+
+func TestExpr_retry(t *testing.T) {
+	// Succeeds on the third attempt: initial run plus two retries.
+	c := &ehCounter{}
+	out, err := expr.Eval(`try { Bump(); if (Get() < 3) { throw(Get()) } else { 1 }; "ok" } catch (err) { retry }`, c)
+	require.NoError(t, err)
+	assert.Equal(t, "ok", out)
+	assert.Equal(t, 3, c.Count)
+
+	// Exhaustion: the body runs at most 4 times (initial + 3 retries),
+	// then a distinct retry-exhaustion error is raised.
+	c = &ehCounter{}
+	_, err = expr.Eval(`try { Bump(); throw(Get()) } catch (err) { retry }`, c)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "retry limit exceeded")
+	assert.Equal(t, 4, c.Count)
+
+	// The exhaustion error is classified as "retry".
+	out, err = expr.Eval(`try { try { Bump(); throw(Get()) } catch (err) { retry } } catch (e) { errtype(e) }`, &ehCounter{})
+	require.NoError(t, err)
+	assert.Equal(t, "retry", out)
+
+	// retry outside of a catch block is a runtime error.
+	_, err = expr.Eval(`retry`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "retry can only be used inside a catch block")
+
+	// retry in a catch block whose filter does not match does not retry.
+	_, err = expr.Eval(`try { throw("x") } catch (e) is "y" { retry }`, nil)
+	require.Error(t, err)
+	assert.Contains(t, err.Error(), "x")
+
+	// Same semantics through the checked compilation path.
+	c = &ehCounter{}
+	program, err := expr.Compile(`try { Bump(); if (Get() < 3) { throw(Get()) } else { 1 }; "ok" } catch (err) { retry }`, expr.Env(&ehCounter{}))
+	require.NoError(t, err)
+	out, err = expr.Run(program, c)
+	require.NoError(t, err)
+	assert.Equal(t, "ok", out)
+	assert.Equal(t, 3, c.Count)
+}
+
+func TestExpr_errtype_unchecked(t *testing.T) {
+	// Classifications that only arise in unchecked programs (the checker
+	// rejects some of these expressions at compile time).
+	tests := []struct {
+		code string
+		env  any
+		want string
+	}{
+		{`try { "a" + 1 } catch (e) { errtype(e) }`, nil, "type"},
+		{`try { [1,2,3]["x"] } catch (e) { errtype(e) }`, nil, "conversion"},
+		{`try { P.X } catch (e) { errtype(e) }`, &ehNilEnv{}, "nil"},
+	}
+	for _, tt := range tests {
+		t.Run(tt.code, func(t *testing.T) {
+			out, err := expr.Eval(tt.code, tt.env)
+			require.NoError(t, err)
+			assert.Equal(t, tt.want, out)
+		})
+	}
+}
+
+func TestExpr_catch_error_value(t *testing.T) {
+	// The caught value is the runtime error itself; string conversion of
+	// it yields the error message.
+	out, err := expr.Eval(`try { throw("a") } catch (e) { e }`, nil)
+	require.NoError(t, err)
+	e, ok := out.(*runtime.Error)
+	require.True(t, ok, "expected *runtime.Error, got %T", out)
+	assert.Equal(t, runtime.ErrorTypeCustom, e.Type)
+	assert.Equal(t, "a", fmt.Sprint(out))
+}
