+// TryNode represents a try/catch/finally expression.
+// Example:
+//
+//	try {
+//		foo()
+//	} catch (err) is "bad" {
+//		"fallback"
+//	} finally {
+//		cleanup()
+//	}
+type TryNode struct {
+	base
+	Body    Node       // Body of the try expression.
+	Catch   *CatchNode // Catch clause, nil when there is none.
+	Finally Node       // Finally body, nil when there is none.
+}
+
+// CatchNode represents a catch clause of a try expression.
+type CatchNode struct {
+	base
+	Name     string // Name of the variable the error is bound to, empty when not bound.
+	Match    string // Substring the error message must contain, empty when catching all errors.
+	HasMatch bool   // If Match is set.
+	Body     Node   // Body of the catch handler.
+}
+
+// RetryNode represents the retry keyword, which re-executes the body of the
+// enclosing try expression. It is only allowed inside a catch block.
+type RetryNode struct {
+	base
+}
