+// parseTryBlock parses the block form of the try expression:
+//
+//	try { ... } catch [name] [is "substring"] { ... } [finally { ... }]
+func (p *Parser) parseTryBlock(start Token) Node {
+	// The "try" identifier was already consumed by parseSecondary.
+	p.expect(Bracket, "{")
+	body := p.parseSequenceExpression()
+	p.expect(Bracket, "}")
+
+	var catch *CatchNode
+	if p.current.Is(Identifier, "catch") {
+		p.next()
+		name := ""
