+				!p.current.Is(Identifier, "is", "catch", "finally") {
+				name = p.current.Value
+				p.next()
+			}
+			p.expect(Bracket, ")")
+		} else if p.current.Is(Identifier) &&
+			!p.current.Is(Identifier, "is", "catch", "finally") {
+			// catch name form
+			name = p.current.Value
+			p.next()
+		}
+		match := ""
+		hasMatch := false
+		if p.current.Is(Identifier, "is") {
+			p.next()
+			if !p.current.Is(String) {
+				p.error("catch is expects a string literal")
+			} else {
+				match = p.current.Value
+				hasMatch = true
+				p.next()
+			}
+		}
+		p.expect(Bracket, "{")
+		handler := p.parseSequenceExpression()
+		p.expect(Bracket, "}")
